import React, { useState } from 'react';
import './LoginAdmin.css'; // Impor file CSS

const LoginAdmin = () => {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [errorMessage, setErrorMessage] = useState(''); // State untuk menyimpan pesan error

  const handleLogin = (e) => {
    e.preventDefault();
    // Validasi login (contoh sederhana)
    if (username === 'admin' && password === 'admin123') { // Gantilah dengan kredensial yang sesuai
      setIsLoggedIn(true);
      setErrorMessage(''); // Reset pesan error jika login berhasil
    } else {
      setErrorMessage('Username atau password salah!'); // Set pesan error jika login gagal
    }
  };

  if (isLoggedIn) {
    // Arahkan ke halaman lain atau lakukan tindakan setelah login berhasil
    // Misalnya, Anda bisa menggunakan routing untuk mengarahkan ke dashboard atau halaman admin lainnya
  }

  return (
    <div className="login-container">
      <div className="login-form">
        <h2 className="login-heading">Login Admin</h2>
        <p className="login-subheading">Silakan masukkan data Anda untuk masuk.</p>

        <form onSubmit={handleLogin}>
          <div className="mb-3">
            <label className="login-label" htmlFor="username">Username:</label>
            <input
              type="text"
              id="username"
              name="username"
              autoComplete="username"
              className="login-input"
              value={username}
              onChange={(e) => setUsername(e.target.value)}
              required
            />
          </div>
          <div className="mb-3">
            <label className="login-label" htmlFor="password">Password:</label>
            <input
              type="password"
              id="password"
              name="password"
              autoComplete="current-password"
              className="login-input"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              required
            />
          </div>
          <button type="submit" className="login-button">Kirim</button>
        </form>

        {/* Tampilkan pesan error jika login gagal */}
        {errorMessage && (
          <p className="error-message">
            {errorMessage}
          </p>
        )}
      </div>
    </div>
  );
};

export default LoginAdmin;
